    // 拼接相对路径/绝对路径的工具函数
    function resolveUrl(baseUrl, path) {
        if (!path) return '';
        // 如果本身已经是完整 http 链接
        if (/^https?:\/\//i.test(path)) {
            return path;
        }
        // 如果是 // 开头，补上协议
        if (path.indexOf('//') === 0) {
            return 'https:' + path;
        }
        // 如果是 / 开头，取主域名拼接
        if (path.indexOf('/') === 0) {
            var m = baseUrl.match(/^(https?:\/\/[^\/]+)/i);
            return m ? m[1] + path : path;
        }
        // 相对路径：取 m3u8 所在目录拼接
